package com.oldschoolnetwork.services.liteinstaller;
import android.content.*;import android.content.pm.*;import android.os.Build;import com.oldschoolnetwork.lite.Transfers;import java.io.*;import java.security.*;import java.util.*;import org.json.*;
final class Payload {
 static final String CERT="f8239cd9deb269e9d4d86893732c27def1936737539c31983d75f1251a49f2d2";
 static List<JSONObject> entries(Context c,boolean store)throws Exception{InputStream input=c.getAssets().open("services.json");ByteArrayOutputStream bytes=new ByteArrayOutputStream();try{byte[] b=new byte[4096];int n;while((n=input.read(b))!=-1)bytes.write(b,0,n);}finally{input.close();}JSONArray all=new JSONObject(new String(bytes.toByteArray(),"UTF-8")).getJSONArray("releases");List<JSONObject> selected=new ArrayList<JSONObject>();for(int i=0;i<all.length();i++){JSONObject release=all.getJSONObject(i);if(("core".equals(release.getString("id"))||store)&&release.getInt("min_sdk")<=Build.VERSION.SDK_INT)selected.add(release);}if(selected.isEmpty()||!"core".equals(selected.get(0).getString("id")))throw new IOException("The bundled Core Lite is not compatible with this device.");return selected;}
 static List<File> prepare(Context c,List<JSONObject> releases)throws Exception{File dir=new File(c.getFilesDir(),"packages");if(!dir.isDirectory()&&!dir.mkdirs())throw new IOException("Cannot create package directory.");List<File> files=new ArrayList<File>();for(JSONObject r:releases){String hash=r.getString("sha256");if(!hash.matches("[0-9a-f]{64}"))throw new IOException("Invalid payload checksum.");File apk=new File(dir,hash+".apk");InputStream in=c.getAssets().open("apks/"+r.getString("asset"));OutputStream out=new FileOutputStream(apk);try{byte[] b=new byte[16384];int n;while((n=in.read(b))!=-1)out.write(b,0,n);}finally{try{in.close();}finally{out.close();}}
  Transfers.verify(c,apk,r.getString("package_name"),r.getInt("version_code"),hash);PackageInfo info=c.getPackageManager().getPackageArchiveInfo(apk.getAbsolutePath(),PackageManager.GET_SIGNATURES);if(info.signatures==null||info.signatures.length==0)info.signatures=Transfers.archiveSignatures(apk);if(info.signatures.length!=1||!CERT.equals(hex(MessageDigest.getInstance("SHA-256").digest(info.signatures[0].toByteArray()))))throw new IOException("The payload is not signed by Oldschool Network.");files.add(apk);}return files;}
 static String hex(byte[] bytes){StringBuilder s=new StringBuilder();for(byte b:bytes)s.append(String.format(Locale.US,"%02x",b&255));return s.toString();}
}
